head.script:
/*
 * WAEA-1454 (11월정기 1694R 확인) pageFrame.setSrc 반환값 확인용 하위 화면 2
 * - 상위 화면(pageFrame_setSrc_returnValue_WAEA-1454_main.xml)의 pageFrame 에 로딩된다.
 * - 공개 함수 getName2() 은 setSrc 반환 직후 pageFrame 에서 바로 호출 가능해야 한다.
 * - onpageload 횟수는 window.__pf1454 로, 전달 파라미터(pfParam)는 getParam() 으로 노출한다.
 */
scwin.param = null;
scwin.onpageload = function () {
    window.__pf1454 = (window.__pf1454 || 0) + 1;
    scwin.param = $p.getParameter("pfParam");
};
scwin.getName2 = function () {
    return "SUB2";
};
scwin.getParam = function () {
    return scwin.param;
};
